CREATE OR REPLACE FUNCTION nexus.collection_id_seq_heal(p_floor bigint)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    c_max_draws CONSTANT integer := 100000;
    v_seq   pg_catalog.regclass;
    v_max   bigint;
    v_floor bigint;
    v_last  bigint;
    v_prev  bigint;
    v_drawn bigint;
    v_draws integer := 0;
BEGIN
    v_seq := pg_catalog.pg_get_serial_sequence('nexus.catalog_collections', 'collection_id')::pg_catalog.regclass;
    IF v_seq IS NULL THEN
        RAISE EXCEPTION 'nexus.collection_id_seq_heal: nexus.catalog_collections.collection_id has no owned sequence'
            USING ERRCODE = 'undefined_object';
    END IF;
    v_last := pg_catalog.pg_sequence_last_value(v_seq);
    SELECT pg_catalog.max(c.collection_id) INTO v_max FROM nexus.catalog_collections c;
    v_floor := GREATEST(COALESCE(p_floor, 0), COALESCE(v_max, 0));
    IF v_floor < 1 OR (v_last IS NOT NULL AND v_floor <= v_last) THEN
        RETURN v_last;
    END IF;
    IF v_floor - COALESCE(v_last, 0) > c_max_draws THEN
        RAISE EXCEPTION 'nexus.collection_id_seq_heal: the floor % is % above the current value % of sequence % (difference %, limit % draws); nothing was drawn. Explicit collection_id values only come from the expand''s registry fill, so a gap this large is unexpected: find the row that holds it. To move the sequence anyway, an operator runs one setval on % to the floor, as the sequence''s owner, with the engine stopped.',
            v_floor, v_floor - COALESCE(v_last, 0), COALESCE(v_last, 0), v_seq, v_floor - COALESCE(v_last, 0), c_max_draws, v_seq
            USING ERRCODE = 'NX229';
    END IF;
    v_prev := v_last;
    LOOP
        v_drawn := pg_catalog.nextval(v_seq);
        v_draws := v_draws + 1;
        IF v_prev IS NOT NULL AND v_drawn < v_prev THEN
            RAISE EXCEPTION 'nexus.collection_id_seq_heal: sequence % wrapped from % to % while drawing to the floor % (it cycles); the floor is above the sequence''s maximum. An operator runs one setval on it, as its owner, with the engine stopped.',
                v_seq, v_prev, v_drawn, v_floor
                USING ERRCODE = 'NX229';
        END IF;
        EXIT WHEN v_drawn >= v_floor;
        IF v_draws >= c_max_draws THEN
            RAISE EXCEPTION 'nexus.collection_id_seq_heal: drew % values of sequence % and reached % short of the floor % (other sessions are drawing too). An operator runs one setval on it to the floor, as its owner, with the engine stopped.',
                v_draws, v_seq, v_drawn, v_floor
                USING ERRCODE = 'NX229';
        END IF;
        v_prev := v_drawn;
    END LOOP;
    RETURN v_drawn;
END
$fn$;

REVOKE EXECUTE ON FUNCTION nexus.collection_id_seq_heal(bigint) FROM PUBLIC;

CREATE OR REPLACE FUNCTION nexus.collection_id_taken(p_id bigint)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $taken$
    SELECT p_id IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.catalog_collections c WHERE c.collection_id = p_id)
$taken$;

REVOKE EXECUTE ON FUNCTION nexus.collection_id_taken(bigint) FROM PUBLIC;

DO $grant$
DECLARE
    seq       text := pg_catalog.pg_get_serial_sequence('nexus.catalog_collections', 'collection_id');
    seq_owner text;
BEGIN
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname = 'nexus_svc') THEN
        GRANT EXECUTE ON FUNCTION nexus.collection_id_seq_heal(bigint) TO nexus_svc;
        GRANT EXECUTE ON FUNCTION nexus.collection_id_taken(bigint) TO nexus_svc;
    ELSE
        RAISE NOTICE 'collections-002: role nexus_svc does not exist; EXECUTE on nexus.collection_id_seq_heal and nexus.collection_id_taken not granted';
    END IF;
    IF seq IS NOT NULL THEN
        SELECT pg_catalog.pg_get_userbyid(c.relowner) INTO seq_owner FROM pg_catalog.pg_class c WHERE c.oid = seq::pg_catalog.regclass;
        IF seq_owner IS DISTINCT FROM current_user THEN
            RAISE WARNING 'collections-002: % is owned by %, not by the migration role %: the definer function runs as the migration role and cannot setval it; a restore that leaves collection_id behind its rows cannot be healed until the migration role owns it', seq, seq_owner, current_user;
        END IF;
    END IF;
END
$grant$;
